CREATE INDEX IF NOT EXISTS "store_lifecycle_emails_store_id_created_at_idx" ON "store_lifecycle_emails" ("store_id", "created_at");

CREATE TABLE IF NOT EXISTS "store_staff" (
  "id" TEXT NOT NULL,
  "store_id" TEXT NOT NULL,
  "user_id" TEXT NOT NULL,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  CONSTRAINT "store_staff_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "store_staff_store_id_fkey" FOREIGN KEY ("store_id") REFERENCES "stores" ("id") ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE UNIQUE INDEX IF NOT EXISTS "store_staff_user_id_store_id_key" ON "store_staff" ("user_id", "store_id");
CREATE INDEX IF NOT EXISTS "store_staff_store_id_idx" ON "store_staff" ("store_id");
CREATE INDEX IF NOT EXISTS "store_staff_user_id_idx" ON "store_staff" ("user_id");

CREATE TABLE IF NOT EXISTS "store_subscriptions" (
  "id" TEXT NOT NULL,
  "store_id" TEXT NOT NULL,
  "plan_code" TEXT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'active',
  "current_period_start" INTEGER,
  "current_period_end" INTEGER,
  "trial_ends_at" INTEGER,
  "cancel_at_period_end" INTEGER NOT NULL DEFAULT 0,
  "provider" TEXT,
  "provider_customer_id" TEXT,
  "provider_subscription_id" TEXT,
  "provider_payment_method_ref" TEXT,
  "payment_method_last4" TEXT,
  "payment_method_brand" TEXT,
  "payment_method_saved_at" INTEGER,
  "billing_method" TEXT,
  "payment_reference" TEXT,
  "orders_over_limit_month" INTEGER,
  "orders_over_limit_notified_at" INTEGER,
  "billing_interval" TEXT NOT NULL DEFAULT 'monthly',
  "pending_plan_code" TEXT,
  "billing_anchor_day" INTEGER,
  "dunning_attempts" INTEGER NOT NULL DEFAULT 0,
  "past_due_since" INTEGER,
  "next_retry_at" INTEGER,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  CONSTRAINT "store_subscriptions_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "store_subscriptions_store_id_fkey" FOREIGN KEY ("store_id") REFERENCES "stores" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT "store_subscriptions_plan_code_fkey" FOREIGN KEY ("plan_code") REFERENCES "plans" ("code") ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT "store_subscriptions_status_chk" CHECK ("status" IN ('trialing', 'active', 'past_due', 'canceled', 'comped')),
  CONSTRAINT "store_subscriptions_cancel_at_period_end_chk" CHECK ("cancel_at_period_end" IN (0, 1)),
  CONSTRAINT "store_subscriptions_billing_interval_check" CHECK ("billing_interval" IN ('monthly', 'yearly')),
  CONSTRAINT "store_subscriptions_payment_method_last4_check" CHECK ("payment_method_last4" IS NULL OR (length("payment_method_last4") = 4 AND "payment_method_last4" NOT GLOB '*[^0-9]*')),
  CONSTRAINT "store_subscriptions_billing_method_check" CHECK ("billing_method" IS NULL OR "billing_method" IN ('card', 'instapay')),
  CONSTRAINT "store_subscriptions_billing_anchor_day_check" CHECK ("billing_anchor_day" IS NULL OR ("billing_anchor_day" BETWEEN 1 AND 31))
);
CREATE UNIQUE INDEX IF NOT EXISTS "store_subscriptions_store_id_key" ON "store_subscriptions" ("store_id");
CREATE UNIQUE INDEX IF NOT EXISTS "store_subscriptions_payment_reference_key" ON "store_subscriptions" ("payment_reference");
CREATE INDEX IF NOT EXISTS "store_subscriptions_plan_code_idx" ON "store_subscriptions" ("plan_code");
CREATE INDEX IF NOT EXISTS "store_subscriptions_status_idx" ON "store_subscriptions" ("status");
CREATE INDEX IF NOT EXISTS "store_subscriptions_current_period_end_idx" ON "store_subscriptions" ("current_period_end");
CREATE INDEX IF NOT EXISTS "store_subscriptions_next_retry_at_idx" ON "store_subscriptions" ("next_retry_at");

CREATE TABLE IF NOT EXISTS "store_usage_snapshots" (
  "id" TEXT NOT NULL,
  "store_id" TEXT NOT NULL,
  "period_start" INTEGER NOT NULL,
  "captured_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "products" INTEGER NOT NULL DEFAULT 0,
  "products_active" INTEGER NOT NULL DEFAULT 0,
  "variants" INTEGER NOT NULL DEFAULT 0,
  "images" INTEGER NOT NULL DEFAULT 0,
  "categories" INTEGER NOT NULL DEFAULT 0,
  "orders" INTEGER NOT NULL DEFAULT 0,
  "revenue_fils" INTEGER NOT NULL DEFAULT 0,
  "customers" INTEGER NOT NULL DEFAULT 0,
  "sessions_proxy" INTEGER NOT NULL DEFAULT 0,
  "carts_with_items" INTEGER NOT NULL DEFAULT 0,
  "product_views" INTEGER NOT NULL DEFAULT 0,
  "ai_calls" INTEGER NOT NULL DEFAULT 0,
  "ai_billable_calls" INTEGER NOT NULL DEFAULT 0,
  "ai_tokens_in" INTEGER NOT NULL DEFAULT 0,
  "ai_tokens_out" INTEGER NOT NULL DEFAULT 0,
  "ai_cost_micros" INTEGER NOT NULL DEFAULT 0,
  "ai_unpriced_calls" INTEGER NOT NULL DEFAULT 0,
  CONSTRAINT "store_usage_snapshots_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "store_usage_snapshots_store_id_fkey" FOREIGN KEY ("store_id") REFERENCES "stores" ("id") ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE UNIQUE INDEX IF NOT EXISTS "store_usage_snapshots_store_id_period_start_key" ON "store_usage_snapshots" ("store_id", "period_start");
CREATE INDEX IF NOT EXISTS "store_usage_snapshots_period_start_idx" ON "store_usage_snapshots" ("period_start" DESC);

CREATE TABLE IF NOT EXISTS "stores" (
  "id" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "name_ar" TEXT,
  "slug" TEXT NOT NULL,
  "domain" TEXT,
  "domain_status" TEXT,
  "pending_domain" TEXT,
  "domain_claimed_at" INTEGER,
  "domain_verified_at" INTEGER,
  "domain_provider" TEXT,
  "email_sender_local_part" TEXT NOT NULL DEFAULT 'noreply',
  "email_domain_id" TEXT,
  "email_domain_status" TEXT,
  "email_domain_verified_at" INTEGER,
  "owner_id" TEXT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'active',
  "billing_suspended_reason" TEXT,
  "billing_suspended_at" INTEGER,
  "plan" TEXT NOT NULL DEFAULT 'starter',
  "logo" TEXT,
  "logo_ar" TEXT,
  "favicon" TEXT,
  "currency" TEXT NOT NULL DEFAULT 'EGP',
  "timezone" TEXT NOT NULL DEFAULT 'Africa/Cairo',
  "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "deleted_at" INTEGER,
  "template" TEXT NOT NULL DEFAULT 'qamar',
  "look" TEXT,
  "is_demo" INTEGER NOT NULL DEFAULT 0,
  "storage_backend" TEXT NOT NULL DEFAULT 'pg',
  CONSTRAINT "stores_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "stores_status_chk" CHECK ("status" IN ('active', 'inactive', 'suspended')),
  CONSTRAINT "stores_plan_chk" CHECK ("plan" IN ('free', 'starter', 'professional', 'enterprise')),
  CONSTRAINT "stores_template_chk" CHECK ("template" IN ('modern', 'classic', 'minimal', 'bold', 'elegant', 'dahab', 'qamar', 'souq', 'jasmine', 'lamma')),
  CONSTRAINT "stores_is_demo_chk" CHECK ("is_demo" IN (0, 1)),
  CONSTRAINT "stores_storage_backend_chk" CHECK ("storage_backend" IN ('pg', 'do')),
  CONSTRAINT "stores_domain_status_check" CHECK ("domain_status" IS NULL OR "domain_status" IN ('pending', 'active', 'failed')),
  CONSTRAINT "stores_billing_suspended_reason_check" CHECK ("billing_suspended_reason" IS NULL OR "billing_suspended_reason" IN ('unpaid', 'over_store_limit')),
  CONSTRAINT "stores_look_format" CHECK ("look" IS NULL OR ("look" GLOB '*.*' AND "look" NOT GLOB '*.*.*' AND "look" NOT GLOB '*[^a-z.]*' AND "look" NOT GLOB '*.' AND substr("look", 1, instr("look", '.') - 1) IN ('qamar', 'souq', 'jasmine', 'lamma', 'dahab')))
);
CREATE UNIQUE INDEX IF NOT EXISTS "stores_slug_key" ON "stores" ("slug");
CREATE UNIQUE INDEX IF NOT EXISTS "stores_domain_key" ON "stores" ("domain");
CREATE INDEX IF NOT EXISTS "stores_owner_id_idx" ON "stores" ("owner_id");
CREATE INDEX IF NOT EXISTS "stores_status_idx" ON "stores" ("status");
CREATE INDEX IF NOT EXISTS "stores_plan_idx" ON "stores" ("plan");
CREATE INDEX IF NOT EXISTS "stores_created_at_idx" ON "stores" ("created_at");
CREATE INDEX IF NOT EXISTS "stores_pending_domain_idx" ON "stores" ("pending_domain");

CREATE TABLE IF NOT EXISTS "system_settings" (
  "id" TEXT NOT NULL,
  "key" TEXT NOT NULL,
  "value" TEXT NOT NULL,
  "category" TEXT NOT NULL DEFAULT 'general',
  "is_public" INTEGER NOT NULL DEFAULT 0,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  CONSTRAINT "system_settings_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "system_settings_value_chk" CHECK (json_valid("value")),
  CONSTRAINT "system_settings_is_public_chk" CHECK ("is_public" IN (0, 1))
);
CREATE UNIQUE INDEX IF NOT EXISTS "system_settings_key_key" ON "system_settings" ("key");
CREATE INDEX IF NOT EXISTS "system_settings_category_idx" ON "system_settings" ("category");

CREATE TABLE IF NOT EXISTS "webhook_events" (
  "id" TEXT NOT NULL,
  "provider" TEXT NOT NULL,
  "idempotency_key" TEXT NOT NULL,
  "store_id" TEXT,
  "payload" TEXT NOT NULL,
  "raw_body" TEXT NOT NULL,
  "signature" TEXT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'received',
  "attempts" INTEGER NOT NULL DEFAULT 0,
  "last_error" TEXT,
  "result_order_id" TEXT,
  "result_status" TEXT,
  "received_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "processed_at" INTEGER,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  CONSTRAINT "webhook_events_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "webhook_events_store_id_fkey" FOREIGN KEY ("store_id") REFERENCES "stores" ("id") ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT "webhook_events_payload_chk" CHECK (json_valid("payload"))
);
CREATE UNIQUE INDEX IF NOT EXISTS "webhook_events_idempotency_key_key" ON "webhook_events" ("idempotency_key");
CREATE INDEX IF NOT EXISTS "webhook_events_status_received_at_idx" ON "webhook_events" ("status", "received_at");
CREATE INDEX IF NOT EXISTS "webhook_events_provider_received_at_idx" ON "webhook_events" ("provider", "received_at");
CREATE INDEX IF NOT EXISTS "webhook_events_store_id_received_at_idx" ON "webhook_events" ("store_id", "received_at" DESC);
